import {objectiveIcon} from './broadcast-hud.js?v=345ebe2e4f45';
import {objectiveRewardText,DRAKES} from './objective-effects.js?v=345ebe2e4f45';
import {OBJECTIVE_NAMES} from './macro-objectives.js?v=345ebe2e4f45';
export function objectiveDecisionMarkup(c,set){
 const {state:s,esc,img,btn}=c,p=set.pending;if(!p)return '';
 const blue=set.blue===s.myTeam,side=blue?'blue':'red',other=blue?'red':'blue',chance=n=>Math.round((blue?n:1-n)*100),skills=p.secure;
 const card=(key,ours)=>{const team=set[key],jungler=set.stats.find(x=>x.team===team&&x.role==='JGL'),tools=skills[key+'Tools'];return `<article><strong>${ours?'우리':'상대'} · ${esc(c.teamName(team))}</strong><span>${esc(p.macros[key==='blue'?0:1])}</span><p>${esc(s.players[jungler?.player]?.name??'정글러')} · 강타 지수 <b>${skills[key+'Smite'].toFixed(1)}</b></p><div class="objective-tools">${tools.length?tools.map(t=>`<span>${img(t.champion)}${esc(t.reason)}</span>`).join(''):'추가 마무리 특성 없음'}</div></article>`;};
 const earned=p.tradePolicy==='earned',trade=blue?p.tradeGold:p.redTradeGold;
 return `<section class="objective-decision" role="dialog" aria-label="오브젝트 운영 선택"><header><div><small>COACH DECISION · ${String(Math.floor(Math.round(p.minute*60)/60)).padStart(2,'0')}:${String(Math.round(p.minute*60)%60).padStart(2,'0')}</small><h2>${p.kind==='dragon'&&p.dragonType?objectiveIcon(p.dragonType):['elder','baron'].includes(p.kind)?objectiveIcon(p.kind):''}${p.kind==='dragon'&&p.dragonType?DRAKES[p.dragonType].name+'용':OBJECTIVE_NAMES[p.kind]} 앞에서 어떻게 운영할까요?</h2></div><span class="badge gold">상대 +${(p.gold[set[other]]-p.gold[s.myTeam]).toLocaleString()}G</span></header><div class="objective-decision-body"><div class="objective-odds"><div><span>우리 한타·교전 승리 확률</span><strong>${chance(p.fightChance)}%</strong></div><div><span>${p.kind==='grubs'?'유충 한 마리당 확보 예상':'양 팀 경합 시 확보 예상'}</span><strong>${chance(p.secureChance)}%</strong></div><div><span>${earned?'추가 라인·정글 자원 상한':'포기 시 골드 교환 예상'}</span><strong>${earned?'0~350G':'+'+Math.round(trade)+'G'}</strong></div></div><p class="objective-reward">${esc(p.objectiveState?objectiveRewardText(p):'이전 버전 경기의 보상 규칙을 적용합니다.')}</p>${p.vision?`<p class="objective-vision">오브젝트 주변 시야: 우리 ${p.vision[blue?0:1]} / 상대 ${p.vision[blue?1:0]} · 교전 확률에 반영</p>`:''}${p.objectiveBounty===s.myTeam?'<p class="objective-reward">우리 팀 오브젝트 현상금 활성 · 테두리 포탑 파괴 시 기본 포탑 보상과 현상금을 별도로 받습니다.</p>':''}<div class="objective-scouting">${card(side,true)}${card(other,false)}</div><p class="small muted">4,500G 이상 열세에서 수동 판단합니다. 교전 전력·골드·성장, 정글러 강타와 마무리 스킬을 반영한 게임 추정입니다. 확보 직전 정글러 생존과 준비 상태에 따라 확률이 달라집니다. ${earned?'포기하면 반대편 라인의 자원과 포탑을 노립니다. 추가 라인·정글 자원은 합계 최대 350G이며 보장되지 않습니다. 포탑은 미니언·공성 인원·수비와 남은 체력에 따라 실제로 파괴해야 별도 골드를 받습니다. 상대도 포기하면 기본 파밍만 진행합니다.':p.objectiveState?'포기하면 오브젝트를 양보하고 사이드·정글·포탑으로 '+(p.tradeRange??[1000,2500]).map(n=>n.toLocaleString()).join('~')+'G를 교환합니다. 팀 운영·사이드 챔피언 성장·전과·조합·공성 강화로 계산하며, 상대도 포기하면 기본 파밍만 진행합니다.':'진행 중인 이전 버전 경기는 당시의 교환 보상을 유지합니다.'}</p></div><div class="objective-actions">${btn('싸우기 · 오브젝트 경합','objective-choice','data-choice="contest"','primary')}${btn(earned?'포기 · 사이드 운영':'포기 · 골드 교환','objective-choice','data-choice="trade"','ghost')}${btn('이번 판단 자동','objective-choice','data-choice="auto"')}${btn('남은 세트 자동 진행','match-auto','','gold')}</div></section>`;
}
